def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    # Initialize the queue for BFS
    queue = deque([(A, 0)])  # (current_string, current_steps)
    visited = set(A)

    while queue:
        current_string, current_steps = queue.popleft()

        # If we reach the target string, return the number of steps
        if current_string == B:
            return current_steps

        # If the number of steps exceeds 10, break the loop
        if current_steps > 10:
            break

        # Apply each transformation rule
        for src, tgt in rules:
            if src in current_string:
                index = current_string.index(src)
                new_string = current_string[:index] + tgt + current_string[index + len(src):]
                if new_string not in visited:
                    visited.add(new_string)
                    queue.append((new_string, current_steps + 1))

    # If we exhaust the queue without finding the target string, return "NO ANSWER!"
    return "NO ANSWER!"

