def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Initialize left and right lists
    left = [1] * n
    right = [1] * n

    # Calculate the longest increasing subsequence ending at each position
    for i in range(1, n):
        if heights[i] > heights[i - 1]:
            left[i] = left[i - 1] + 1

    # Calculate the longest decreasing subsequence starting from each position
    for i in range(n - 2, -1, -1):
        if heights[i] > heights[i + 1]:
            right[i] = right[i + 1] + 1

    # Find the maximum number of students that can form a valid choir formation
    max_choir = 0
    for i in range(n):
        max_choir = max(max_choir, left[i] + right[i] - 1)

    # The minimum number of students to leave
    return n - max_choir

