def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Find the index of the max height
    max_height_index = heights.index(max(heights))

    # Calculate the number of students to leave before the max height
    left = 0
    for i in range(max_height_index):
        if heights[i] >= heights[i + 1]:
            left += 1

    # Calculate the number of students to leave after the max height
    right = 0
    for i in range(max_height_index, n - 1):
        if heights[i] <= heights[i + 1]:
            right += 1

    # Total students to leave is the sum of students to leave before and after the max height
    return left + right

